// SideSheet.tsx
import React from "react";
import "./SideSheet.scss";
import ModalTitle from "../modal/ModalTitle/ModalTitle";
import ModalContent from "../modal/ModalContent/ModalContent";
import ModalActions from "../modal/ModalActions/ModalActions";
import { ButtonProps } from "../button";

export interface SideSheetProps {
    /**
     * Unique identifier for the sideSheet component
     */
    id: string;

    /**
     * Controls modal visibility
    */
    open?: boolean;

    /**
     * Main heading text displayed in modal header
     */
    title?: string;

    /**
     * Controls Side Sheet width size preset
     */
    size?: "xs" | "s" | "m" |  "l" ;

    /**
    * Callback for modal close (via close button/ESC/outside click)
    */
    onClose?: () => void;

    /**
     * Toggle visibility of close button
     * @default true
     */
    // showClose?: boolean;
    /**
     * Define the side sheet placement right or left   
     */
    placement?: "left" | "right";
    /**
     * Toggle visibility of header
     * @default true
     */
    showHeader?: boolean;

    /**
     * Toggle visibility of divider
     * @default true
     */
    //  showDivider?: boolean; 

    /**
     * Label text for cancel button
     */
    cancelButtonLabel?: string;
    /**
     * Label text for primary action button
     */
    confirmButtonLabel?: string;

    /**
     * Callback for cancel button click (renders if provided)
     */
    onCancel?: () => void;
    /**
     * Callback for confirm button click (renders if provided)
     */
    onConfirm?: () => void;

    /**
     * Custom props for cancel button component
     * @type {Partial<ButtonProps>}
     */
    cancelButtonProps?: Partial<ButtonProps>;
    /**
     * Custom props for confirm button component
     * @type {Partial<ButtonProps>}
     */
    confirmButtonProps?: Partial<ButtonProps>;
    /**
     * Custom action buttons to override default button layout
     * @type {React.ReactNode}
     */
    customButtons?: React.ReactNode;

    /**
    * Optional thumbnail/image displayed in header
    * @type {React.ReactNode}
    */
    thumbnail?: React.ReactNode;

    /**
    * Modal content (main body)
     */
    children?: React.ReactNode;
}

export const SideSheet: React.FC<SideSheetProps> = ({
  id,
  open=false,
  title,
  size = "s",
  cancelButtonLabel,
  confirmButtonLabel,
  onCancel,
  onConfirm,
  onClose,
  placement="right",
  // showClose,
  showHeader = true,
  // showDivider,
  cancelButtonProps,
  confirmButtonProps,
  customButtons,
  thumbnail,
  children,

}) => {
   
  const sizeClassMap: Record<NonNullable<SideSheetProps['size']>, string> = {
    xs: "modal-extra-small",
    s: "modal-small",
    m: "modal-medium",
    l: "modal-large"
  };

  const sideSheetClassName = `mpa-sideSheet ${open ? "open" : ""} ${size ? sizeClassMap[size] : ""} ${placement}`;
  
  const contentTitle = thumbnail ? title : undefined;


  return (
    <div className={sideSheetClassName} id={id}>
      <div className="side-sheet-container">
        {showHeader && 
          <ModalTitle
              id={id}
              title={title}
              thumbnail={thumbnail}
              onClose={onClose}
              showClose={true}
          />
        } 
        
        <ModalContent title={contentTitle}>{children}</ModalContent>

        <ModalActions
            id={id}
            cancelButtonLabel={cancelButtonLabel}
            confirmButtonLabel={confirmButtonLabel}
            onCancel={onCancel}
            onConfirm={onConfirm}
            cancelButtonProps={cancelButtonProps}
            confirmButtonProps={confirmButtonProps}
            customButtons={customButtons}
        />
      </div>
    </div>
  );
};

export default SideSheet;
